tl.fromTo('#dm-elem-s0 .shockwave-2', { r: 0, opacity: 1, strokeWidth: 2 }, { r: 180, opacity: 0, strokeWidth: 0, duration: 1.5, ease: 'power2.out', repeat: 2 }, 0.8);
